import { CoinPrice } from '@cetus/types/src/common-types'
import { extractStructTagFromType } from '@cetusprotocol/common-sdk'
import { StateCreator, create } from 'zustand'

interface TokenState {
  coinPriceObj: Record<string, CoinPrice>
  setPriceObj: (obj: Record<string, CoinPrice>) => void
  clearPriceObj: (coinTypeList: string[]) => void
}

const store: StateCreator<TokenState> = (set, get) => {
  return {
    coinPriceObj: {},
    setPriceObj: (obj: Record<string, CoinPrice>) => {
      const tokensObj = get().coinPriceObj
      const updatedObj = { ...tokensObj }

      // 避免price_change  被其他价格接口对象覆盖
      Object.entries(obj).forEach(([key, newPrice]) => {
        const existingPrice = tokensObj[key]
        updatedObj[key] = {
          ...newPrice,
          price_change: existingPrice?.price_change || newPrice.price_change
        }
      })

      set({
        coinPriceObj: updatedObj
      })
    },
    clearPriceObj: (coinTypeList: string[]) => {
      const tokensObj = get().coinPriceObj
      coinTypeList.forEach(coinType => {
        delete tokensObj[extractStructTagFromType(coinType).full_address]
      })
      set({
        coinPriceObj: {
          ...tokensObj
        }
      })
    }
  }
}

const useTokenPriceStore = create(store)
export default useTokenPriceStore
