import { create } from 'zustand'
import { SdkFactory } from './sdkFactory'

interface SdkStore {
  sdkFactory: SdkFactory
  account: string | null
  setAccount: (account: string | null) => void
  rpcs: string[]
  setRpcs: (rpcs: string[]) => void
  currentRpc: string
  setCurrentRpc: (rpc: string) => void
  initializeSdk: () => void
  isInitialized: boolean
  setIsInitialized: (isInitialized: boolean) => void
  providers: string[]
  setProviders: (value: string[]) => void
}

const sdkFactory = new SdkFactory()

export const useSdkStore = create<SdkStore>((set, get) => ({
  isInitialized: false,
  sdkFactory,
  account: null,
  rpcs: [],
  currentRpc: '',
  providers: [],
  setAccount: account => {
    set({ account })
    // 同步账户到 SDK
    if (account) {
      get().sdkFactory.setSenderAddress(account)
    } else {
      get().sdkFactory.setSenderAddress('')
    }
  },
  setRpcs: rpcs => {
    set({ rpcs })
    // 如果 RPC 列表有变化，重新初始化 SDK
    get().initializeSdk()
  },
  setCurrentRpc: rpc => {
    set({ currentRpc: rpc })
    if (get().isInitialized) {
      sdkFactory.switchRpc(rpc)
    } else {
      get().initializeSdk()
    }
    // 如果当前 RPC 地址有变化，重新初始化 SDK
  },
  initializeSdk: () => {
    const { currentRpc, rpcs } = get()
    console.log('Initializing SDK with currentRpc:', currentRpc, 'and rpcs:', rpcs)
    sdkFactory.initialize(currentRpc, rpcs)
    set({ isInitialized: true })
  },
  setIsInitialized: isInitialized => {
    set({ isInitialized })
  },
  setProviders: (value: string[]) => {
    if (!get().isInitialized) {
      sdkFactory.initialize(get().currentRpc, get().rpcs)
    }
    set({ providers: value })
    const vaultsSdk = sdkFactory.getSdk('vaults')
    vaultsSdk.updateProviders(value)
  }
}))
