import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Box, Popover, PopoverBody, PopoverContent, PopoverContentProps, PopoverProps, PopoverTrigger, Portal } from '@chakra-ui/react'
import { useEffect, useRef, useState } from 'react'

interface CetusTooltipProps extends PopoverProps {
  children: React.ReactNode
  tooltip: React.ReactNode
  maxW?: PopoverContentProps['maxW']
  bodyPadding?: string
  showTooltip?: boolean
}

function CetusTooltip({ children, tooltip, placement, maxW = '320px', bodyPadding = '8px', showTooltip = true }: CetusTooltipProps) {
  const { isApp } = useWindowWidth()
  const [isOpen, setIsOpen] = useState(false)
  const triggerRef = useRef<HTMLDivElement>(null)

  // 监听移动端的外部点击
  useEffect(() => {
    if (!isApp || !showTooltip) return

    const handleClickOutside = (e: MouseEvent) => {
      if (triggerRef.current && !triggerRef.current.contains(e.target as Node)) {
        setIsOpen(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [isApp, showTooltip])

  const handleOpen = () => {
    if (showTooltip) setIsOpen(true)
  }

  const trigger = (
    <Box as="button" ref={triggerRef} onClick={isApp ? handleOpen : undefined}>
      {children}
    </Box>
  )

  return (
    <Popover
      isLazy
      trigger={isApp ? 'click' : 'hover'}
      isOpen={isApp ? isOpen : undefined} // 只在移动端控制状态
      onClose={() => setIsOpen(false)}
      placement={placement}
      autoFocus={false}
      returnFocusOnClose={false}
      gutter={4}
    >
      <PopoverTrigger>{trigger}</PopoverTrigger>

      {showTooltip && (
        <Portal>
          <PopoverContent w="fit-content" maxW={maxW}>
            <PopoverBody p={bodyPadding} fontSize="12px" w="fit-content">
              {tooltip}
            </PopoverBody>
          </PopoverContent>
        </Portal>
      )}
    </Popover>
  )
}

export default CetusTooltip
